import {DECOR,decorAction,ownsDecor} from './seasonal-decor.mjs';
import {HOF,HOF_LANES} from './hof-layout.mjs';
import {HAY_FIELD} from './alp-life.mjs';
import {STAFF,businessAction,guestCapacity,roomCapacity,guestOrigin} from './alp-business.mjs';
import {ESTATE_PLOTS} from './estate-plots.mjs';
import {UPGRADES,buildEstate,harvestEstate,restByStream} from './estate.mjs';
import {exchangeInventory,itemName,money} from './progression.mjs';
export function createEstatePanels({getState,capture,show,changed}){
const $=id=>document.getElementById(id),message=m=>m?'<p class="panel-message" role="status">'+m+'</p>':'';
function workshop(m=''){capture();const s=getState(),inside=s.position.region==='alp'&&s.position.inside,completed=Object.keys(UPGRADES).filter(k=>s.estate.built[k]).length;show('<span class="eyebrow">PORTMANN · DEINE ALPWIRTSCHAFT</span><h2>Ausbauen & Crafting</h2>'+message(m)+'<p>'+completed+' / '+Object.keys(UPGRADES).length+' Ausbauten · '+money(s.coins)+'</p><button id="estate-business">Betrieb, Gäste & Personal</button><button id="estate-land">Bauflächen ansehen</button><button id="estate-decor">Dekorationen für Haus & Alp</button><p>Beginne mit der Alphütte. Restaurant, Panoramabad, Spielplatz, Gästeetage und Hotel folgen Schritt für Schritt. Alle Flächen sind fest reserviert: Heuwiese im Westen, Gastwirtschaft auf den östlichen Hangterrassen. Gebaut wird an der Hüttenwerkbank.</p><div class="item-grid">'+Object.entries(UPGRADES).map(([id,u])=>{const done=!!s.estate.built[id],locked=u.requires&&!s.estate.built[u.requires],p=ESTATE_PLOTS[u.plot];return '<article class="item-card"><span class="eyebrow">'+(done?'GEBAUT':locked?'NOCH GESPERRT':'FREIGESCHALTET')+'</span><h3>'+u.name+'</h3><p>'+u.text+'</p>'+(p?'<p>Reservierte Fläche: '+p.w+' × '+p.d+' m · '+p.title+'</p>':'')+(u.requires?'<p>Voraussetzung: '+UPGRADES[u.requires].name+'</p>':'')+'<p>'+Object.entries(u.ingredients).map(([k,n])=>n+' × '+itemName(k)+' ('+(s.inventory[k]||0)+')').join(' · ')+'</p><p>'+money(u.cost||0)+' · '+u.energy+' Energie</p><button data-build="'+id+'" '+(!inside||done||locked?'disabled':'')+'>'+(done?'✓ Gebaut':locked?'Zuerst Voraussetzung bauen':'Ausbau herstellen')+'</button></article>';}).join('')+'</div><p>'+(!inside?'Zum Bauen in die Alphütte gehen. Pläne kannst du überall ansehen.':'Materialien werden erst nach erfolgreicher Prüfung abgezogen.')+'</p>');$('estate-business').onclick=()=>business();$('estate-land').onclick=()=>land();$('estate-decor').onclick=()=>decoration();for(const el of document.querySelectorAll('[data-build]'))el.onclick=()=>{capture();const r=buildEstate(s,el.dataset.build,exchangeInventory);if(r.ok)changed();workshop(r.message);};}
function land(){capture();const s=getState(),rect=(p,fill,stroke='#697954')=>'<rect x="'+(p.x-p.w/2)+'" y="'+(p.z-p.d/2)+'" width="'+p.w+'" height="'+p.d+'" rx=".5" fill="'+fill+'" stroke="'+stroke+'" stroke-width=".25"/>',names=Object.entries(ESTATE_PLOTS).filter(([k])=>k!=='tools');show('<span class="eyebrow">DEIN HOF · FESTE BAUFLÄCHEN</span><h2>Platz zum Wachsen</h2><svg viewBox="-47 -28 101 76" role="img" aria-label="Lageplan: Heuwiese westlich, Hütte und Stall im Norden, Gastwirtschaft auf den Ostterrassen" style="width:100%;background:#e0e9ce;border-radius:16px">'+HOF_LANES.map(([a,b,w])=>'<path d="M '+a.join(' ')+' L '+b.join(' ')+'" fill="none" stroke="#c0a37d" stroke-width="'+w+'"/>').join('')+rect(HAY_FIELD,'#bed08d')+rect(HOF.house,'#ad8155')+rect(HOF.barn,'#9e7956')+rect(HOF.coop,'#c7b890')+'<ellipse cx="'+HOF.pond.x+'" cy="'+HOF.pond.z+'" rx="'+HOF.pond.rx+'" ry="'+HOF.pond.rz+'" fill="#85b9be"/>'+names.map(([k,p])=>rect(p,s.estate.built[k]?'#92b68a':'#f1e4c5')+'<text x="'+p.x+'" y="'+(p.z+.6)+'" text-anchor="middle" font-size="1.5" fill="#244137">'+p.title+'</text>').join('')+'<text x="-36" y="7" text-anchor="middle" font-size="2" fill="#244137">Heuwiese</text><text x="-16" y="-7" text-anchor="middle" font-size="1.9" fill="#fff">Alphütte</text><text x="1.5" y="-13" text-anchor="middle" font-size="1.9" fill="#fff">Stall</text><text x="-7" y="27" font-size="2" fill="#244137">↓ Talweg bleibt frei</text><text x="-22" y="-25" font-size="2" fill="#244137">↑ Wald & Berge</text></svg><p>Grün: gebaut. Sandfarben: reserviert. Die Heuwiese umfasst 120 m². Hotel, Restaurant, Bad und Spielplatz haben eigene Terrassen. Die Zusatzweide liegt am östlichen Rand, das grosse Heulager im Westen. Ein weiterer Stock nutzt die Restaurantfläche.</p><button id="estate-plans">Zu den Ausbauplänen</button>');$('estate-plans').onclick=()=>workshop();}
function business(m=''){capture();const s=getState(),b=s.estate.business,u=s.estate.built,served=b.servedDay===s.day?b.served:0,rooms=b.roomDay===s.day?b.rooms:0;show('<span class="eyebrow">ALPWIRTSCHAFT · TAG '+s.day+'</span><h2>Gäste & Personal</h2>'+message(m)+'<p>'+money(s.coins)+' · '+b.visitors+' Gäste insgesamt · Zufriedenheit '+(b.visitors?Math.round(b.satisfaction/b.visitors)+' / 100':'noch keine Bewertung')+' · Umsatz '+money(b.revenue)+'</p><article class="item-card"><h3>Alp-Restaurant</h3><p>'+(u.restaurant?'Heute '+served+' / '+guestCapacity(s)+' bewirtet. Nächster Gast: '+guestOrigin(s,served)+'. Eine gekochte Mahlzeit aus dem Rucksack wird serviert.':'Zuerst Alphütte und Restaurant ausbauen.')+'</p><button data-business="serve" '+(!u.restaurant||served>=guestCapacity(s)?'disabled':'')+'>Gast bewirten</button></article><article class="item-card"><h3>Berghotel</h3><p>'+(u.hotel?rooms+' / '+roomCapacity(s)+' Übernachtungen heute. Pro Buchung: 1 Wasser und 1 Brot, ab CHF 30 Einnahmen.':'Wird nach dem Restaurant-Ausbau freigeschaltet.')+'</p><button data-business="room" '+(!u.hotel||rooms>=roomCapacity(s)?'disabled':'')+'>Zimmer & Frühstück vorbereiten</button></article><button data-business="spa" '+(!u.spa||b.spaDay===s.day?'disabled':'')+'>Panoramabad geniessen · bis zu 35 Energie</button><h3>Dein Team</h3><p>Einmalige Einstellung, danach Lohn pro ausgeführtem Auftrag. Kein Geldverlust bei geschlossenem Spiel. Fachkräfte verwenden deine echten Vorräte; Höhlenkäse muss weiterhin im Keller reifen.</p><div class="item-grid">'+Object.entries(STAFF).map(([id,p])=>'<article class="item-card"><h3>'+p.name+'</h3><p>'+(b.staff[id]?'Angestellt · ':money(p.fee)+' Einstellung · ')+money(p.wage)+' pro Auftrag</p><p>Voraussetzung: '+UPGRADES[p.requires].name+'</p><button data-business="hire:'+id+'" '+(!u[p.requires]||b.staff[id]?'disabled':'')+'>'+(b.staff[id]?'✓ Angestellt':'Einstellen')+'</button>'+(['dairy','chocolate'].includes(id)?'<p>'+(id==='dairy'?'2 Milch + 1 Lab → 1 frischer Käse':'2 Kakao + 1 Milch + 1 Honig → 2 Schokoladen')+'</p><button data-business="'+id+'" '+(!b.staff[id]?'disabled':'')+'>Produktionsauftrag</button>':'')+'</article>').join('')+'</div><p>Dieser Betriebsstand verwaltet Tagesgäste und Buchungen. Sichtbar anreisende Touristengruppen und ein laufender Tischservice folgen als weitere Entwicklungsphase.</p><button id="estate-plans">Zurück zu den Ausbauplänen</button>');$('estate-plans').onclick=()=>workshop();for(const el of document.querySelectorAll('[data-business]'))el.onclick=()=>{capture();const r=businessAction(s,el.dataset.business);if(r.ok)changed();business(r.message||'Auftrag erledigt.');};}
function field(id,m=''){capture();const s=getState();show('<span class="eyebrow">ALP-LANDWIRTSCHAFT · TAG '+s.day+'</span><h2>'+(id==='cocoa'?'Portmann-Schokoladenbohnen':id==='corn'?'Das grössere Kornfeld':'Der kleine Kornstreifen')+'</h2>'+message(m)+'<p>Die Ernte folgt deinem Spieltag. Wenn das Spiel geschlossen ist, vergeht keine Anbauzeit. Neue Anlagen tragen ab dem folgenden Tag. Grössere Anlagen entstehen über «Alp & Weide ausbauen» im Rezeptbuch.</p><button id="field-harvest" class="primary">Ernten · 3 Energie</button><button id="field-plans">Ausbaupläne ansehen</button>');$('field-harvest').onclick=()=>{capture();const r=harvestEstate(s,id,exchangeInventory);if(r.ok)changed();field(id,r.message);};$('field-plans').onclick=()=>workshop();}
function fire(m=''){capture();show('<span class="eyebrow">BERGBACH · EIN ORT DER RUHE</span><h2>Wasser, Feuer und Bergluft</h2>'+message(m)+'<p>Die Fische ziehen zwischen den Steinen vorbei. Hier gibt es nichts zu schaffen und keine Uhr, die drängt.</p><button id="stream-rest" class="primary">Am Bach rasten · kostenlos</button>');$('stream-rest').onclick=()=>{capture();const r=restByStream(getState());if(r.ok)changed();fire(r.message);};}
function decoration(m=''){capture();const s=getState(),d=s.estate.decor;show('<span class="eyebrow">CRAFTING · DEIN ZUHAUSE</span><h2>Dekorationen für Haus & Alp</h2>'+message(m)+'<p>Einmal herstellen, dauerhaft freischalten. Material wird nur beim Herstellen verbraucht. Kürbisse gibt es am Dorfmarkt und im Dorfladen. Die Dekosaison ist frei wählbar; sie stellt nicht das Wetter um.</p><button data-season="autumn">Herbst auf der Alp</button><button data-season="winter">Winter auf der Alp</button><div class="item-grid">'+Object.entries(DECOR).map(([id,v])=>'<article class="item-card"><h3>'+v.name+'</h3><p>'+v.text+'</p><p>'+Object.entries(v.ingredients).map(([k,n])=>n+' × '+itemName(k)+' ('+(s.inventory[k]||0)+')').join(' · ')+' · '+v.energy+' Energie</p><button data-decorcraft="'+id+'" '+(d.unlocked.includes(id)?'disabled':'')+'>'+(d.unlocked.includes(id)?'Dauerhaft freigeschaltet':'An der Hüttenwerkbank herstellen')+'</button><button data-decorout="'+id+'" '+(!ownsDecor(s,id)?'disabled':'')+'>'+(d.placed.includes(id)?'Von der Alp wegräumen':'Auf der Alp aufstellen')+'</button><button data-decorin="'+id+'" '+(!ownsDecor(s,id)?'disabled':'')+'>In der Wohnstube wechseln</button></article>').join('')+'</div><button id="decor-back">Zurück zum Ausbau</button>');const run=(a,id)=>{capture();const r=decorAction(s,a,id);if(r.ok)changed();decoration(r.message);};for(const el of document.querySelectorAll('[data-season]'))el.onclick=()=>run('season',el.dataset.season);for(const [selector,key,action]of [['decorcraft','decorcraft','craft'],['decorout','decorout','outdoor'],['decorin','decorin','indoor']])for(const el of document.querySelectorAll('[data-'+selector+']'))el.onclick=()=>run(action,el.dataset[key]);$('decor-back').onclick=()=>workshop();}
return{workshop,business,field,fire,decoration};}
